// Repositories/ClockEntryRepository.cs
public sealed class ClockEntryRepository
{
    private readonly List<ClockEntry> _clockEntries = new();

    public void SaveClockEntry(ClockEntry clockEntry)
    {
        _clockEntries.Add(clockEntry);
    }

    public IEnumerable<ClockEntry> GetEmployeeClockEntries(
        int employeeId,
        DateTime startDate,
        DateTime endDate)
    {
        return _clockEntries.Where(entry =>
            entry.EmployeeId == employeeId &&
            entry.Clockout is not null &&
            entry.ClockIn >= startDate &&
            entry.ClockIn <= endDate);
    }

    public ClockEntry? GetOpenClockEntry(int employeeId)
    {
        return _clockEntries.FirstOrDefault(entry =>
            entry.EmployeeId == employeeId && entry.Clockout is null);
    }
}

// Add as a new Session 11 section at the end of App/Program.cs.
var repository = new ClockEntryRepository();

var completedEntry = new ClockEntry(1, new DateTime(2026, 1, 15, 9, 0, 0));
completedEntry.ClockOutEntry(new DateTime(2026, 1, 15, 17, 0, 0));

var openEntry = new ClockEntry(1, new DateTime(2026, 1, 16, 9, 0, 0));

repository.SaveClockEntry(completedEntry);
repository.SaveClockEntry(openEntry);

IEnumerable<ClockEntry> completedEntries = repository.GetEmployeeClockEntries(
    1,
    new DateTime(2026, 1, 1),
    new DateTime(2026, 1, 31));

ClockEntry? currentOpenEntry = repository.GetOpenClockEntry(1);

Console.WriteLine($"Completed entries: {completedEntries.Count()}");
Console.WriteLine($"Open entry found: {currentOpenEntry is not null}");
